type Table0085 string

const (
	// Table0085RecordComingOverIsACorrectionAndThusReplacesAFinalResult - Record coming over is a correction and thus replaces a final result
	Table0085RecordComingOverIsACorrectionAndThusReplacesAFinalResult Table0085 = "C"
	// Table0085DeletesTheOBXRecord - Deletes the OBX record
	Table0085DeletesTheOBXRecord Table0085 = "D"
	// Table0085FinalResultsCanOnlyBeChangedWithACorrectedResult - Final results; Can only be changed with a corrected result.
	Table0085FinalResultsCanOnlyBeChangedWithACorrectedResult Table0085 = "F"
	// Table0085SpecimenInLabResultsPending - Specimen in lab; results pending
	Table0085SpecimenInLabResultsPending Table0085 = "I"
	// Table0085NotAskedUsedToAffirmativelyDocumentThatTheObservationIdentifiedInTheOBXWasNotSoughtWhenTheUniversalServiceIDInOBR4ImpliesThatItWouldBeSought - Not asked; used to affirmatively document that the observation identified in the OBX was not sought when the universal service ID in OBR-4 implies that it would be sought.
	Table0085NotAskedUsedToAffirmativelyDocumentThatTheObservationIdentifiedInTheOBXWasNotSoughtWhenTheUniversalServiceIDInOBR4ImpliesThatItWouldBeSought Table0085 = "N"
	// Table0085OrderDetailDescriptionOnlyNoResult - Order detail description only (no result)
	Table0085OrderDetailDescriptionOnlyNoResult Table0085 = "O"
	// Table0085PreliminaryResults - Preliminary results
	Table0085PreliminaryResults Table0085 = "P"
	// Table0085ResultsEnteredNotVerified - Results entered -- not verified
	Table0085ResultsEnteredNotVerified Table0085 = "R"
	// Table0085PartialResults - Partial results
	Table0085PartialResults Table0085 = "S"
	// Table0085ResultsStatusChangeToFinalWithoutRetransmittingResultsAlreadySentAsPreliminaryEGRadiologyChangesStatusFromPreliminaryToFinal - Results status change to final without retransmitting results already sent as ‘preliminary.’  E.g., radiology changes status from preliminary to final
	Table0085ResultsStatusChangeToFinalWithoutRetransmittingResultsAlreadySentAsPreliminaryEGRadiologyChangesStatusFromPreliminaryToFinal Table0085 = "U"
	// Table0085PostOriginalAsWrongEGTransmittedForWrongPatient - Post original as wrong, e.g., transmitted for wrong patient
	Table0085PostOriginalAsWrongEGTransmittedForWrongPatient Table0085 = "W"
	// Table0085ResultsCannotBeObtainedForThisObservation - Results cannot be obtained for this observation
	Table0085ResultsCannotBeObtainedForThisObservation Table0085 = "X"
)

